package dev.infend.skyrimtext;
import org.junit.Test;
import static org.junit.Assert.*;
public class LiviaStoryTest {
    private GameEngine world(){GameEngine g=new GameEngine();g.started=true;g.mode="WORLD";g.progress.startId="Хелген";g.progress.location="Солитьюд";g.canonicalStage=3;return g;}
    private void reach(GameEngine g){g.livia.choose(g,"LIVIA:open");g.livia.choose(g,"LIVIA:listen");g.livia.choose(g,"LIVIA:records");g.livia.choose(g,"LIVIA:witnesses");assertEquals(3,g.livia.stage);}
    @Test public void locationAndHelgenGuard(){GameEngine g=world();g.canonicalStage=2;assertFalse(g.livia.available(g));g.canonicalStage=3;g.progress.location="Ривервуд";assertFalse(g.livia.available(g));g.progress.location="Солитьюд";assertTrue(g.livia.available(g));}
    @Test public void redemptionAndRomancePersist() throws Exception {GameEngine g=world();reach(g);g.livia.choose(g,"LIVIA:redeem");assertEquals("Искупление",g.livia.ending);g.livia.choose(g,"LIVIA:join");assertTrue(g.livia.active());g.livia.choose(g,"LIVIA:romance");assertFalse(g.livia.romance);for(int i=0;i<7;i++){g.day++;g.livia.choose(g,"LIVIA:talk");}g.livia.choose(g,"LIVIA:romance");assertTrue(g.livia.romance);LiviaStory saved=LiviaStory.restore(g.livia.save());assertTrue(saved.active());assertTrue(saved.romance);assertEquals("Искупление",saved.ending);}
    @Test public void revengeIsFinal(){GameEngine g=world();reach(g);g.livia.choose(g,"LIVIA:revenge");assertEquals(4,g.livia.stage);assertFalse(g.livia.available(g));assertFalse(g.livia.active());g.livia.choose(g,"LIVIA:join");assertFalse(g.livia.following);}
    @Test public void alternateStartAndTerminalAi() throws Exception {GameEngine g=world();g.progress.startId="Ривервуд";g.canonicalStage=0;assertTrue(g.livia.available(g));reach(g);g.livia.choose(g,"LIVIA:revenge");assertTrue(g.livia.aiContext(g).contains("Не возвращать"));assertFalse(LiviaStory.restore(g.livia.save()).survivor());}
    @Test public void duelAndCompanionBounds() throws Exception {GameEngine g=world();reach(g);g.battleKind="LIVIA_DUEL";g.livia.victory(g);assertEquals("Последний поединок",g.livia.ending);assertFalse(g.livia.active());assertEquals(0,g.livia.assist(2,5));assertFalse(LiviaStory.restore(g.livia.save()).survivor());}
    @Test public void distinctEpiloguesAndReplay() throws Exception {GameEngine g=world();reach(g);g.livia.choose(g,"LIVIA:redeem");assertTrue(g.livia.epilogueTitle().contains("семей"));g.livia.choose(g,"LIVIA:epilogue:0");assertEquals(1,g.livia.epilogue);g.livia.choose(g,"LIVIA:epilogue:1");assertEquals(1,g.livia.epilogue);g.day++;g.livia.choose(g,"LIVIA:epilogue:1");assertEquals(2,g.livia.epilogue);LiviaStory restored=LiviaStory.restore(g.livia.save());assertEquals(2,restored.epilogue);assertTrue(restored.history.length()>=5);GameEngine h=world();reach(h);h.livia.choose(h,"LIVIA:forgive");assertTrue(h.livia.epilogueTitle().contains("памятное"));}
    @Test public void companionStaminaAndTactics() throws Exception {GameEngine g=world();reach(g);g.livia.choose(g,"LIVIA:forgive");g.livia.choose(g,"LIVIA:join");g.livia.choose(g,"LIVIA:stance");assertEquals(1,g.livia.stance);assertEquals(6,g.livia.protect(20));g.livia.companionStamina=0;assertEquals(0,g.livia.assist(2,20));assertEquals(0,g.livia.protect(20));g.livia.rest(2);assertEquals(24,g.livia.companionStamina);assertEquals(24,LiviaStory.restore(g.livia.save()).companionStamina);}
    @Test public void castleReturn(){GameEngine g=world();g.region=3;g.mode="SOLITUDE:1";g.choose("SOLITUDE:livia");assertEquals("LIVIA",g.mode);g.choose("LIVIA:exit");assertEquals("SOLITUDE:1",g.mode);}
    @Test public void independentLifeAndSave() throws Exception {GameEngine g=world();reach(g);g.livia.choose(g,"LIVIA:redeem");g.livia.daily(g);int days=g.livia.life.independentDays;g.livia.daily(g);assertEquals(days,g.livia.life.independentDays);g.day++;g.livia.daily(g);assertEquals(days+1,g.livia.life.independentDays);assertEquals(days+1,LiviaStory.restore(g.livia.save()).life.independentDays);}
    @Test public void marriageAndSeparation() throws Exception {GameEngine g=world();reach(g);g.livia.choose(g,"LIVIA:forgive");g.livia.trust=90;g.livia.respect=90;g.livia.affection=90;g.livia.epilogue=3;g.livia.choose(g,"LIVIA:romance");g.livia.life.love=85;g.livia.dates=3;g.livia.choose(g,"LIVIA:engage");assertTrue(g.livia.life.engaged);g.livia.choose(g,"LIVIA:join");g.progress.location="Рифтен";g.livia.choose(g,"LIVIA:marry");assertFalse(g.livia.life.married);g.day++;g.livia.choose(g,"LIVIA:marry");assertTrue(g.livia.life.married);assertTrue(LiviaStory.restore(g.livia.save()).life.married);g.livia.choose(g,"LIVIA:break");assertFalse(g.livia.life.married);assertFalse(g.livia.romance);}
    @Test public void equipmentConservation() throws Exception {GameEngine g=world();reach(g);g.livia.choose(g,"LIVIA:forgive");String id="Железный меч";assertTrue(LiviaLife.eligible(id));assertTrue(g.progress.addItem(id,1));assertTrue(g.livia.life.transfer(g,g.livia,id,true));assertEquals(0,g.progress.quantity(id));assertTrue(g.livia.life.equip(g,g.livia,id));assertEquals(id,LiviaStory.restore(g.livia.save()).life.gear.optString("weapon"));assertTrue(g.livia.life.transfer(g,g.livia,id,false));assertEquals(1,g.progress.quantity(id));assertEquals("",g.livia.life.gear.optString("weapon"));}
    @Test public void homeReturnAndSave() throws Exception {GameEngine g=world();g.region=3;reach(g);g.livia.choose(g,"LIVIA:forgive");g.livia.romance=true;g.livia.life.married=true;assertTrue(g.fixShop.home.buy(SolitudeHome.HOUSE));g.livia.choose(g,"LIVIA:home");assertTrue(g.livia.life.sharedHome);g.mode=SolitudeHome.MODE;g.choose("SOLITUDE:home:livia");assertEquals(LiviaStory.MODE,g.mode);assertTrue(g.livia.homeReturn);assertTrue(LiviaStory.restore(g.livia.save()).homeReturn);g.choose("LIVIA:exit");assertEquals(SolitudeHome.MODE,g.mode);}
    @Test public void groupTrustOnlyForPresentCompanions() throws Exception {GameEngine g=world();reach(g);g.livia.choose(g,"LIVIA:forgive");g.livia.choose(g,"LIVIA:join");g.katherine.enabled=true;g.katherine.stage=5;g.katherine.following=true;g.livia.choose(g,"LIVIA:group");assertEquals(53,g.livia.life.katherineTrust);assertEquals(50,g.livia.life.almaTrust);g.livia.choose(g,"LIVIA:group");assertEquals(53,g.livia.life.katherineTrust);assertEquals(53,LiviaStory.restore(g.livia.save()).life.katherineTrust);}
    @Test public void talkReplayAndDisable(){GameEngine g=world();reach(g);g.livia.choose(g,"LIVIA:forgive");g.livia.choose(g,"LIVIA:talk");int trust=g.livia.trust;g.livia.choose(g,"LIVIA:talk");assertEquals(trust,g.livia.trust);g.livia.choose(g,"LIVIA:join");assertTrue(g.livia.active());assertTrue(g.livia.setEnabled(g,false));assertFalse(g.livia.active());assertEquals(0,g.livia.assist(2,20));assertEquals("WORLD",g.mode);}
}
